from dataclasses import dataclass


@dataclass
class Num:
    v: int


@dataclass
class Add:
    l: "Expr"
    r: "Expr"


@dataclass
class Mul:
    l: "Expr"
    r: "Expr"


Expr = Num | Add | Mul


def eval_expr(e: Expr) -> int:
    """Evaluate an expression tree: Num yields v, Add sums, Mul multiplies."""
    if isinstance(e, Num):
        return e.v
    if isinstance(e, Add):
        return eval_expr(e.l) + eval_expr(e.r)
    if isinstance(e, Mul):
        return eval_expr(e.l) * eval_expr(e.r)
    raise TypeError(f"unknown expression: {e!r}")


def test_num() -> None:
    assert eval_expr(Num(7)) == 7


def test_add() -> None:
    assert eval_expr(Add(Num(2), Num(3))) == 5


def test_mul_nested() -> None:
    assert eval_expr(Mul(Add(Num(1), Num(2)), Num(4))) == 12


def test_negative_values() -> None:
    assert eval_expr(Mul(Num(-3), Num(5))) == -15


def test_deep_tree() -> None:
    e = Add(Mul(Num(2), Num(3)), Add(Num(4), Mul(Num(0), Num(9))))
    assert eval_expr(e) == 10
